# 048 - registrazione e info del PC

import sys


def traccia(testo):
    riga = '[048] %s' % testo
    try:
        print(riga)
    except Exception:
        pass
    try:
        import datetime
        import os
        d = os.path.join(os.environ.get('LOCALAPPDATA') or
                         os.path.expanduser('~'), 'KaraDom')
        os.makedirs(d, exist_ok=True)
        with open(os.path.join(d, 'patch048.log'), 'a', encoding='utf-8') as f:
            f.write('%s  %s%s' % (
                datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S'),
                riga, chr(10)))
    except Exception:
        pass


CODICE_SPLASH = '"""\nSplash Screen - Schermata iniziale con gestione licenze\n"""\n\nimport tkinter as tk\ntry:\n    from .theme import Theme\nexcept:\n    from theme import Theme\nfrom tkinter import messagebox\nimport json\nimport webbrowser\nimport urllib.parse\nimport urllib.request\nimport os\nimport sys\nimport time\nimport socket\nimport hashlib\nimport platform\nimport threading\nfrom pathlib import Path\nfrom datetime import datetime\n\nfrom .licensing import (\n    get_hardware_id, generate_serial, is_licensed, \n    save_license, load_license\n)\nfrom .i18n import _\nfrom .ui_scale import S, F, geo\n\n\n# ────────────────────────────────────────────────────────────\n# Raccolta info PC silenziosa (NON visibili all\'utente finale).\n# Sono inviate al server insieme alla richiesta di licenza per\n# permettere al gestionale di tracciare HW ID e nome del PC.\n# ────────────────────────────────────────────────────────────\n# ────────────────────────────────────────────────────────────\n# LA REGISTRAZIONE (utente, 13-09): si scarica senza registrarsi, ma per\n# ENTRARE bisogna registrarsi e dire cosa si vuole — la prova di un\'ora, la\n# Home o la Pro. Il server risponde con la licenza se il pagamento risulta.\n# Fatta una volta su questo PC, ai riavvii successivi non si chiede piu\'\n# niente: si entra da soli nella prova.\n# ────────────────────────────────────────────────────────────\nREGISTRA_URL = "https://karadom.it/api/registra_app.php"\n\n\ndef _file_registrazione():\n    d = os.path.join(os.environ.get(\'LOCALAPPDATA\') or os.path.expanduser(\'~\'),\n                     \'KaraDom\')\n    try:\n        os.makedirs(d, exist_ok=True)\n    except Exception:\n        pass\n    return os.path.join(d, \'_registrato.json\')\n\n\ndef giorni_prova_rimasti():\n    """Quanti giorni restano alla prova su questo PC (None se non si sa).\n\n    La scadenza la decide il SERVER alla prima registrazione (15 giorni) e\n    viaggia con la risposta; qui si tiene l\'ultima vista, cosi\' la barra in\n    alto sa cosa scrivere anche senza rete.\n    """\n    try:\n        with open(_file_registrazione(), encoding=\'utf-8\') as f:\n            d = json.load(f)\n        scadenza = str(d.get(\'prova_scadenza\') or \'\').strip()[:10]\n        if not scadenza:\n            return None\n        from datetime import date\n        anno, mese, giorno = scadenza.split(\'-\')\n        return (date(int(anno), int(mese), int(giorno)) - date.today()).days\n    except Exception:\n        return None\n\n\ndef _versione_programma():\n    for come in (\'moduli.versione\', \'versione\'):\n        try:\n            return __import__(come, fromlist=[\'APP_VERSION\']).APP_VERSION\n        except Exception:\n            continue\n    return \'\'\n\n\ndef _registrazione_fatta(serial):\n    """True se su QUESTO computer la registrazione e\' gia\' stata fatta."""\n    try:\n        with open(_file_registrazione(), encoding=\'utf-8\') as f:\n            d = json.load(f)\n        return bool(d.get(\'serial\')) and str(d.get(\'serial\')) == str(serial)\n    except Exception:\n        return False\n\n\ndef _segna_registrazione(serial, dati=None):\n    try:\n        d = dict(dati or {})\n        d[\'serial\'] = serial\n        d[\'quando\'] = datetime.now().strftime(\'%Y-%m-%d %H:%M:%S\')\n        with open(_file_registrazione(), \'w\', encoding=\'utf-8\') as f:\n            json.dump(d, f)\n    except Exception:\n        pass\n\n\ndef _riga_tecnica_di(hd_id, chipset_id):\n    """La riga piccola sotto il seriale: impronta, versione, patch attive.\n\n    ⛔ NON DEVE MAI FAR SALTARE LO SPLASH. E\' la finestra che si apre a chi non\n       ha licenza: se un errore qui impedisse di aprirla, il cliente non\n       potrebbe nemmeno far partire la prova. Ogni pezzo sta nel suo `try` e\n       quello che non si sa diventa un trattino.\n    """\n    hw = \'—\'\n    try:\n        hw = (_collect_pc_fingerprint(hd_id, chipset_id)[0] or \'—\')[:16]\n    except Exception:\n        pass\n    ver = \'—\'\n    for come in (\'moduli.versione\', \'versione\'):\n        try:\n            ver = __import__(come, fromlist=[\'APP_VERSION\']).APP_VERSION\n            break\n        except Exception:\n            continue\n    patch = \'—\'\n    try:\n        from . import hotfix\n        r = hotfix.riassunto() or {}\n        attive = sorted(n for n, v in r.items() if v and v[0])\n        patch = (\',\'.join(attive) if attive\n                 else (\'nessuna\' if r else \'—\'))\n    except Exception:\n        pass\n    return \'hw %s   ·   v %s   ·   patch %s\' % (hw, ver, patch)\n\n\ndef _collect_pc_fingerprint(cpu_id: str, motherboard_id: str) -> tuple[str, str]:\n    """\n    Ritorna (hw_id, pc_name).\n\n    hw_id:  hash SHA-256 (primi 32 char) della stringa CPU|MOTHERBOARD\n            → identificativo hardware univoco e stabile, NON reversibile.\n    pc_name: hostname della macchina (es. \'DESKTOP-A1B2C3\').\n             Fallback su platform.node() o stringa vuota.\n    """\n    try:\n        raw = f"{cpu_id or \'\'}|{motherboard_id or \'\'}"\n        hw_id = hashlib.sha256(raw.encode(\'utf-8\')).hexdigest()[:32].upper()\n    except Exception:\n        hw_id = ""\n\n    pc_name = ""\n    try:\n        pc_name = socket.gethostname() or ""\n    except Exception:\n        pass\n    if not pc_name:\n        try:\n            pc_name = platform.node() or ""\n        except Exception:\n            pc_name = ""\n\n    return hw_id, pc_name\n\n\nclass TrialCountdown:\n    """Gestisce il countdown trial con popup finale"""\n    \n    def __init__(self, duration_minutes=30):\n        self.duration = duration_minutes * 60  # in secondi\n        self.start_time = None\n        self.running = False\n        self.root = None\n    \n    def start(self, root):\n        """Avvia il countdown"""\n        self.root = root\n        self.start_time = time.time()\n        self.running = True\n        self._check_time()\n    \n    def _check_time(self):\n        """Controlla il tempo rimanente"""\n        if not self.running or not self.root:\n            return\n        \n        elapsed = time.time() - self.start_time\n        remaining = self.duration - elapsed\n        \n        if remaining <= 10:\n            # Ultimi 10 secondi - mostra popup countdown\n            self._show_final_countdown(int(remaining))\n        elif remaining <= 0:\n            self._expire()\n        else:\n            # Controlla ogni secondo\n            self.root.after(1000, self._check_time)\n    \n    def _show_final_countdown(self, seconds):\n        """Mostra popup con countdown finale"""\n        if seconds <= 0:\n            self._expire()\n            return\n        \n        # Crea popup se non esiste\n        if not hasattr(self, \'countdown_window\') or not self.countdown_window.winfo_exists():\n            self.countdown_window = tk.Toplevel(self.root)\n            self.countdown_window.title(_("Trial in scadenza"))\n            self.countdown_window.geometry(geo("350x200"))\n            self.countdown_window.resizable(False, False)\n            self.countdown_window.configure(bg=\'#1a1a2e\')\n            self.countdown_window.attributes(\'-topmost\', True)\n            self.countdown_window.protocol("WM_DELETE_WINDOW", lambda: None)  # Blocca chiusura\n            \n            # Icona\n            try:\n                self.countdown_window.iconbitmap("img/icona.ico")\n            except:\n                pass\n            \n            # Centra\n            self.countdown_window.update_idletasks()\n            x = (self.countdown_window.winfo_screenwidth() - S(350)) // 2\n            y = (self.countdown_window.winfo_screenheight() - S(200)) // 2\n            self.countdown_window.geometry(geo(f"350x200+{x}+{y}"))\n            \n            tk.Label(self.countdown_window, text=_("⏱️ TRIAL SCADUTO"), \n                    font=F(\'Arial\', 16, \'bold\'), bg=\'#1a1a2e\', fg=\'#ff4444\').pack(pady=S(20))\n            \n            tk.Label(self.countdown_window, text=_("Il programma si chiuderà tra:"), \n                    font=F(\'Arial\', 11), bg=\'#1a1a2e\', fg=\'white\').pack()\n            \n            self.countdown_label = tk.Label(self.countdown_window, text=str(seconds), \n                                           font=F(\'Arial\', 48, \'bold\'), bg=\'#1a1a2e\', fg=\'#ffcc00\')\n            self.countdown_label.pack(pady=S(10))\n            \n            tk.Label(self.countdown_window, text=_("secondi"), \n                    font=F(\'Arial\', 10), bg=\'#1a1a2e\', fg=\'#888888\').pack()\n        else:\n            # Aggiorna countdown\n            self.countdown_label.config(text=str(seconds))\n        \n        # Prossimo secondo\n        self.root.after(1000, lambda: self._show_final_countdown(seconds - 1))\n    \n    def _expire(self):\n        """Trial scaduto - chiudi l\'app"""\n        self.running = False\n        try:\n            if hasattr(self, \'countdown_window\') and self.countdown_window.winfo_exists():\n                self.countdown_window.destroy()\n        except:\n            pass\n        \n        # Chiudi tutto\n        os._exit(0)\n    \n    def stop(self):\n        """Ferma il countdown (se si attiva licenza)"""\n        self.running = False\n\n\n# Variabile globale per il trial\n_trial_manager = None\n\n\ndef get_trial_manager():\n    """Ottiene l\'istanza del trial manager"""\n    global _trial_manager\n    if _trial_manager is None:\n        _trial_manager = TrialCountdown(30)  # 30 minuti\n    return _trial_manager\n\n\ndef _altezza_richiesta(w):\n    """Quanto spazio verticale vuole davvero il contenuto di w.\n\n    ⚠️ Solo winfo_reqheight: sommare y+reqheight dei figli NON funziona, perche\'\n    il footer e\' ancorato in basso e la sua y vale quanto tutta la finestra —\n    il conto tornava sempre "non ci sta" e il logo veniva ridotto al minimo.\n    """\n    w.update_idletasks()\n    return w.winfo_reqheight()\n\n\ndef _restringi_spazi(w, fattore):\n    """Riduce i margini verticali di tutti i widget, ricorsivamente.\n\n    Non tocca i testi ne\' i colori: toglie solo il vuoto. Su una finestra\n    pensata per 880 px, e\' quello che permette di starci in 688 senza che\n    l\'utente debba scorrere.\n    """\n    for c in w.winfo_children():\n        try:\n            info = c.pack_info()\n        except Exception:\n            info = None\n        if info:\n            nuovo = {}\n            for chiave in (\'pady\', \'ipady\'):\n                v = info.get(chiave)\n                if isinstance(v, (tuple, list)):\n                    nuovo[chiave] = tuple(int(int(x) * fattore) for x in v)\n                elif v not in (None, \'\', 0, \'0\'):\n                    nuovo[chiave] = int(int(v) * fattore)\n            if nuovo:\n                c.pack_configure(**nuovo)\n        # i bottoni hanno anche un\'imbottitura loro\n        try:\n            if int(c.cget(\'pady\') or 0) > 2:\n                c.configure(pady=max(2, int(int(c.cget(\'pady\')) * fattore)))\n        except Exception:\n            pass\n        _restringi_spazi(c, fattore)\n\n\ndef _rimpicciolisci_logo(w, quota):\n    """Ridisegna il logo piu\' basso (quota = altezza massima in pixel)."""\n    for c in w.winfo_children():\n        try:\n            if c.cget(\'image\'):\n                from PIL import Image, ImageTk\n                p = getattr(w, \'_kd_logo_path\', None) or getattr(c, \'_kd_logo_path\', None)\n                if p:\n                    img = Image.open(p)\n                    img.thumbnail((10000, quota), Image.Resampling.LANCZOS)\n                    nuova = ImageTk.PhotoImage(img)\n                    c.configure(image=nuova)\n                    c.image = nuova\n                    return True\n        except Exception:\n            pass\n        if _rimpicciolisci_logo(c, quota):\n            return True\n    return False\n\n\ndef _respira(finestra, avanzo):\n    """Rimette un po\' di aria in cima: i campi non devono partire incollati\n    al logo. Si usa solo lo spazio che avanza davvero."""\n    if avanzo < 12:\n        return\n    for c in finestra.winfo_children():\n        try:\n            info = c.pack_info()\n        except Exception:\n            continue\n        if info.get(\'side\') in (None, \'\', \'top\'):\n            v = info.get(\'pady\', 0)\n            base = int(v[0]) if isinstance(v, (tuple, list)) else int(v or 0)\n            c.pack_configure(pady=(base + min(int(avanzo / 3), 20), base))\n            return\n\n\ndef _stringi_per_stare(finestra, disponibile):\n    """Stringe il contenuto finche\' non entra nello spazio dato.\n\n    Si va per gradi e ci si ferma al PRIMO che basta: si toglie solo lo stretto\n    necessario, cosi\' il logo resta piu\' grande che si puo\'.\n    """\n    if _altezza_richiesta(finestra) <= disponibile:\n        return\n\n    # 1) via il vuoto fra i campi: e\' spazio che non serve a nessuno\n    _restringi_spazi(finestra, 0.35)\n\n    # 2) il logo si tocca DOPO, e si tiene il piu\' grande che ci sta: e\' la\n    #    prima cosa che si vede, non va sacrificato prima del necessario\n    for alto in (150, 132, 116, 100, 86, 72, 58):\n        _rimpicciolisci_logo(finestra, alto)\n        if _altezza_richiesta(finestra) <= disponibile:\n            _respira(finestra, disponibile - _altezza_richiesta(finestra))\n            return\n\n    # 3) se ancora non basta, ultima stretta\n    _restringi_spazi(finestra, 0.4)\n\n\nclass SplashScreen:\n    """Splash screen con gestione licenze"""\n    \n    # URL del form contatti online\n    CONTACT_URL = "https://karadom.it/send_contact.php"\n    \n    def __init__(self, on_continue, on_trial, email_dest="registrazione@karadom.it"):\n        self.on_continue = on_continue\n        self.on_trial = on_trial\n        self.email_dest = email_dest\n        self.license_error = None\n        \n        # Ottieni info hardware\n        self.hd_id, self.chipset_id = get_hardware_id()\n        self.serial = generate_serial(self.hd_id, self.chipset_id)\n        \n        # Controlla se già licenziato PRIMA di creare la finestra\n        valid, error_msg, _edition = is_licensed()\n        if valid:\n            self.on_continue()\n            return\n        \n        # Salva eventuale messaggio di errore\n        self.license_error = error_msg\n        \n        self.root = tk.Tk()\n        self.root.title(_("KaraDom - Attivazione"))\n\n        # ===== ALTEZZA CHE STA NELLO SCHERMO =====\n        # Erano 880 px fissi: su un portatile 1366x768 il fondo della finestra\n        # — dove stanno il bottone della prova e il codice licenza — finiva\n        # sotto il bordo dello schermo e non si poteva raggiungere.\n        # Ora la finestra non supera mai lo spazio disponibile; se lo spazio non\n        # basta, il contenuto scorre (vedi _create_widgets).\n        self._h_voluta = S(880)\n        _libera = self.root.winfo_screenheight() - S(80)   # barra applicazioni + bordi\n        self._h_reale = max(S(420), min(self._h_voluta, _libera))\n        self.root.geometry(f"{S(500)}x{self._h_reale}")\n        self.root.minsize(S(460), S(380))\n        self.root.resizable(False, True)\n        self.root.configure(bg=\'#1a1a2e\')\n        \n        # Icona finestra\n        try:\n            self.root.iconbitmap("img/icona.ico")\n        except:\n            pass\n        \n        # Centra finestra\n        self.root.update_idletasks()\n        x = (self.root.winfo_screenwidth() - S(500)) // 2\n        y = max(0, (self.root.winfo_screenheight() - self._h_reale) // 2)\n        self.root.geometry(f"{S(500)}x{self._h_reale}+{x}+{y}")\n        \n        self._create_widgets()\n\n        # ⭐ LA FINESTRA SI ACCORCIA DA SOLA fino a quanto serve davvero\n        #    (utente, 13-09: "la parte bassa della maschera non c\'e\' scritto\n        #    niente, accorcia"). Prima erano 880 px fissi e sotto il footer\n        #    restava una fascia vuota.\n        try:\n            self.root.update_idletasks()\n            serve = _altezza_richiesta(self.root) + S(12)\n            nuova = max(S(420), min(serve, _libera))\n            if nuova < self._h_reale:\n                self._h_reale = nuova\n                y = max(0, (self.root.winfo_screenheight() - nuova) // 2)\n                self.root.geometry(f"{S(500)}x{nuova}+{x}+{y}")\n        except Exception:\n            pass\n\n        # ⛔ NIENTE POPUP quando la licenza semplicemente NON C\'E\' (utente,\n        #    13-09): chi apre il programma appena installato deve trovare la\n        #    schermata di registrazione, non un avviso da chiudere.\n        #    L\'avviso resta solo per i guai veri: licenza revocata, bloccata,\n        #    manomessa o non confermata dal server.\n        _guai = (\'revoc\', \'blocc\', \'manomess\', \'non confermata\', \'scadut\')\n        if self.license_error and any(g in str(self.license_error).lower() for g in _guai):\n            self.root.after(500, lambda: messagebox.showerror(\n                _("Licenza non valida"),\n                _("⚠️ {err}\\n\\nInserisci una licenza valida per continuare.").format(err=self.license_error)\n            ))\n    \n    def _get_logo_path(self):\n        """Ottiene il percorso del logo"""\n        if getattr(sys, \'frozen\', False) or (\'__compiled__\' in globals()):\n            base = Path(sys.argv[0]).resolve().parent\n        else:\n            base = Path(__file__).parent.parent\n        \n        possible_paths = [\n            base / "img" / "logo_splash.png",   # logo con sfondo = colore splash\n            Path("img/logo_splash.png"),\n            base / "img" / "logo_stage.png",\n            Path("img/logo_stage.png"),\n            base / "img" / "logo.png",\n            Path("img/logo.png"),\n        ]\n        \n        for path in possible_paths:\n            if path.exists():\n                return str(path)\n        return None\n    \n    def _create_widgets(self):\n        """Crea i widget dello splash"""\n\n        self._crea_contenuto()\n\n        # Niente barra di scorrimento: se il contenuto sfora, si STRINGE.\n        # Prima i vuoti fra un campo e l\'altro, poi il logo. Chi apre KaraDom\n        # deve vedere subito tutto, bottone della prova compreso.\n        try:\n            _stringi_per_stare(self.root, self._h_reale - S(16))\n            # e la finestra si adatta a quanto serve davvero, invece di restare\n            # mezza vuota: piu\' e\' bassa, meno rischia di uscire dallo schermo\n            self.root.update_idletasks()\n            serve = self.root.winfo_reqheight() + S(8)\n            if S(400) < serve < self._h_reale:\n                self._h_reale = serve\n        except Exception:\n            pass\n\n    def _crea_contenuto(self):\n        """Il contenuto vero e proprio della finestra di attivazione."""\n\n        # ===== LOGO =====\n        logo_frame = tk.Frame(self.root, bg=\'#1a1a2e\')\n        logo_frame.pack(pady=S(15))\n        \n        logo_path = self._get_logo_path()\n        if logo_path:\n            try:\n                from PIL import Image, ImageTk\n                img = Image.open(logo_path)\n                # mantiene le proporzioni (il logo orizzontale non va schiacciato)\n                img.thumbnail((S(340), S(150)), Image.Resampling.LANCZOS)\n                self.logo_img = ImageTk.PhotoImage(img)\n                logo_label = tk.Label(logo_frame, image=self.logo_img, bg=\'#1a1a2e\')\n                # serve a _rimpicciolisci_logo: su schermi bassi il logo si\n                # ridisegna piu\' piccolo invece di rubare spazio ai campi\n                logo_label._kd_logo_path = logo_path\n                logo_label.pack()\n                tk.Label(self.root, text=_("Sistema Karaoke Professionale"), \n                font=F(\'Arial\', 9), bg=\'#1a1a2e\', fg=\'#888888\').pack()\n            except:\n                tk.Label(logo_frame, text="🎤", font=F(\'Arial\', 50), \n                        bg=\'#1a1a2e\', fg=\'#0078D7\').pack()\n        else:\n            tk.Label(logo_frame, text="🎤", font=F(\'Arial\', 50), \n                    bg=\'#1a1a2e\', fg=\'#0078D7\').pack()\n        \n        # Titolo\n        #tk.Label(self.root, text=_("KaraDom"), font=F(\'Arial\', 22, \'bold\'),\n        #        bg=\'#1a1a2e\', fg=\'white\').pack()\n        #tk.Label(self.root, text=_("Sistema Karaoke Professionale"), \n        #        font=F(\'Arial\', 9), bg=\'#1a1a2e\', fg=\'#888888\').pack()\n        \n        # ===== FORM LICENZA =====\n        form_frame = tk.Frame(self.root, bg=\'#1a1a2e\')\n        form_frame.pack(pady=S(15), padx=S(30), fill=\'x\')\n        \n        # Nome\n        tk.Label(form_frame, text=_("Nome"), font=F(\'Arial\', 12, \'bold\'),\n                bg=\'#1a1a2e\', fg=\'white\', anchor=\'w\').pack(fill=\'x\')\n        self.entry_nome = tk.Entry(form_frame, font=F(\'Arial\', 12),\n                                   bg=\'#2d2d44\', fg=\'white\',\n                                   insertbackground=\'white\', relief=\'flat\')\n        self.entry_nome.pack(fill=\'x\', ipady=S(6), pady=(0, S(8)))\n        \n        # Cognome\n        tk.Label(form_frame, text=_("Cognome"), font=F(\'Arial\', 12, \'bold\'),\n                bg=\'#1a1a2e\', fg=\'white\', anchor=\'w\').pack(fill=\'x\')\n        self.entry_cognome = tk.Entry(form_frame, font=F(\'Arial\', 12),\n                                      bg=\'#2d2d44\', fg=\'white\',\n                                      insertbackground=\'white\', relief=\'flat\')\n        self.entry_cognome.pack(fill=\'x\', ipady=S(6), pady=(0, S(8)))\n        \n        # Email\n        tk.Label(form_frame, text=_("Email"), font=F(\'Arial\', 12, \'bold\'),\n                bg=\'#1a1a2e\', fg=\'white\', anchor=\'w\').pack(fill=\'x\')\n        self.entry_email = tk.Entry(form_frame, font=F(\'Arial\', 12),\n                                    bg=\'#2d2d44\', fg=\'white\',\n                                    insertbackground=\'white\', relief=\'flat\')\n        self.entry_email.pack(fill=\'x\', ipady=S(6), pady=(0, S(8)))\n\n        # Telefono (serve all\'assistenza; non obbligatorio)\n        tk.Label(form_frame, text=_("Telefono"), font=F(\'Arial\', 12, \'bold\'),\n                bg=\'#1a1a2e\', fg=\'white\', anchor=\'w\').pack(fill=\'x\')\n        self.entry_telefono = tk.Entry(form_frame, font=F(\'Arial\', 12),\n                                       bg=\'#2d2d44\', fg=\'white\',\n                                       insertbackground=\'white\', relief=\'flat\')\n        self.entry_telefono.pack(fill=\'x\', ipady=S(6), pady=(0, S(8)))\n\n        # Seriale (readonly)\n        tk.Label(form_frame, text=_("Seriale PC"), font=F(\'Arial\', 12, \'bold\'),\n                bg=\'#1a1a2e\', fg=\'white\', anchor=\'w\').pack(fill=\'x\')\n        \n        serial_frame = tk.Frame(form_frame, bg=\'#1a1a2e\')\n        serial_frame.pack(fill=\'x\', pady=(0, S(8)))\n        \n        # Il seriale va LETTO e ricopiato al telefono: era verde acceso su\n        # fondo chiaro (readonly schiarisce lo sfondo) e si leggeva male.\n        # Bianco su fondo scuro, grassetto e a spaziatura fissa: le cifre e le\n        # lettere non si confondono (0/O, 1/I).\n        self.entry_serial = tk.Entry(serial_frame,\n                                     font=F(\'Arial\', 12, \'bold\'),\n                                     bg=\'#2d2d44\', fg=\'#ffffff\',\n                                     readonlybackground=\'#2d2d44\',\n                                     disabledbackground=\'#2d2d44\',\n                                     insertbackground=\'white\', relief=\'flat\',\n                                     state=\'readonly\')\n        self.entry_serial.pack(side=\'left\', fill=\'x\', expand=True, ipady=S(6))\n        \n        self.entry_serial.config(state=\'normal\')\n        self.entry_serial.insert(0, self.serial)\n        self.entry_serial.config(state=\'readonly\')\n        \n        # Bottone registrazione + richiesta licenza\n        # ⭐ La licenza nasce dal SERIALE e dall\'IMPRONTA insieme (utente,\n        #    13-09), quindi tutti e due si leggono qui e viaggiano con la\n        #    registrazione.\n        self.btn_registra = tk.Button(serial_frame, text=_("✋ Registrati"),\n                                      font=F(\'Arial\', 9, \'bold\'),\n                                      bg=\'#0078D7\', fg=\'white\', relief=\'flat\',\n                                      cursor=\'hand2\', padx=S(12),\n                                      command=self._registra_dialogo)\n        self.btn_registra.pack(side=\'right\', padx=(S(8), 0), ipady=S(4))\n\n        # Impronta del PC (hw id): si legge come il seriale\n        tk.Label(form_frame, text=_("HW ID"), font=F(\'Arial\', 12, \'bold\'),\n                bg=\'#1a1a2e\', fg=\'white\', anchor=\'w\').pack(fill=\'x\')\n        self.entry_hw = tk.Entry(form_frame, font=F(\'Arial\', 12, \'bold\'),\n                                 bg=\'#2d2d44\', fg=\'#ffffff\',\n                                 readonlybackground=\'#2d2d44\',\n                                 disabledbackground=\'#2d2d44\',\n                                 insertbackground=\'white\', relief=\'flat\',\n                                 state=\'normal\')\n        try:\n            self.hw_id, self.pc_name = _collect_pc_fingerprint(self.hd_id, self.chipset_id)\n        except Exception:\n            self.hw_id, self.pc_name = \'\', \'\'\n        self.entry_hw.insert(0, self.hw_id or \'—\')\n        self.entry_hw.config(state=\'readonly\')\n        self.entry_hw.pack(fill=\'x\', ipady=S(5), pady=(0, S(8)))\n\n        # ⭐ Impronta hardware, versione e patch attive, SOTTO il seriale.\n        #    Serve all\'assistenza: al telefono il cliente legge questa riga e\n        #    si sa subito su che PC si sta lavorando e se le patch sono\n        #    arrivate. Prima l\'impronta non si vedeva da nessuna parte e le\n        #    patch si potevano solo chiedere — con risposte sbagliate anche in\n        #    buona fede (vedi `hotfix.riassunto`, che riporta cio\' che il\n        #    caricatore ha VISTO, non cio\' che si spera).\n        #\n        # ⚠️ UNA RIGA SOLA, carattere piccolo: questa finestra su 1366x768 non\n        #    ci stava gia\' prima e il bottone della prova finiva fuori schermo.\n        #    Niente blocchi alti (vedi la nota sull\'altezza dello splash).\n        tk.Label(form_frame, text=_riga_tecnica_di(self.hd_id, self.chipset_id),\n                 font=F(\'Consolas\', 8), bg=\'#1a1a2e\', fg=\'#7a7a95\',\n                 anchor=\'w\', justify=\'left\').pack(fill=\'x\', pady=(0, S(4)))\n\n        # Separatore\n        tk.Frame(form_frame, bg=\'#444444\', height=S(1)).pack(fill=\'x\', pady=S(12))\n        \n        # Campo Licenza\n        tk.Label(form_frame, text=_("Codice Licenza"), font=F(\'Arial\', 12, \'bold\'),\n                bg=\'#1a1a2e\', fg=\'white\', anchor=\'w\').pack(fill=\'x\')\n        self.entry_license = tk.Entry(form_frame, font=F(\'Arial\', 12),\n                                      bg=\'#2d2d44\', fg=\'#ffcc00\',\n                                      insertbackground=\'white\', relief=\'flat\',\n                                      justify=\'center\')\n        self.entry_license.pack(fill=\'x\', ipady=S(8), pady=(0, S(8)))\n        \n        # Bottone Attiva\n        btn_activate = tk.Button(form_frame, text=_("✓ ATTIVA LICENZA"),\n                                font=F(\'Arial\', 11, \'bold\'),\n                                bg=\'#28a745\', fg=\'white\', relief=\'flat\',\n                                cursor=\'hand2\', pady=S(8),\n                                command=self._activate_license)\n        btn_activate.pack(fill=\'x\', pady=(0, S(15)))\n        \n        btn_activate.bind("<Enter>", lambda e: btn_activate.config(bg=\'#218838\'))\n        btn_activate.bind("<Leave>", lambda e: btn_activate.config(bg=\'#28a745\'))\n        \n        # ===== SEPARATORE =====\n        sep_frame = tk.Frame(self.root, bg=\'#1a1a2e\')\n        sep_frame.pack(fill=\'x\', padx=S(30))\n        tk.Frame(sep_frame, bg=\'#444444\', height=S(1)).pack(fill=\'x\')\n        tk.Label(sep_frame, text=_(" oppure "), bg=\'#1a1a2e\', fg=\'#666666\',\n                font=F(\'Arial\', 9)).place(relx=0.5, rely=0.5, anchor=\'center\')\n        \n        # ===== ACCESSO SENZA LICENZA =====\n        trial_frame = tk.Frame(self.root, bg=\'#1a1a2e\')\n        trial_frame.pack(pady=S(15))\n        \n        self.lbl_trial = tk.Label(trial_frame, text=_("Non hai una licenza?"),\n                font=F(\'Arial\', 10), bg=\'#1a1a2e\', fg=\'#aaaaaa\')\n        self.lbl_trial.pack()\n\n        # ⛔ SPENTO FINCHE\' NON CI SI REGISTRA (utente, 13-09: "se l\'utente non\n        #    si registra il bottone per l\'accesso diventa inibito"). Chi si e\'\n        #    gia\' registrato su questo PC lo trova acceso e non deve rifare\n        #    niente: entra da solo dopo pochi secondi.\n        self.gia_registrato = _registrazione_fatta(self.serial)\n        self.btn_trial = tk.Button(trial_frame, text=_("▶ ACCEDI (Prova 60 minuti)"),\n                             font=F(\'Arial\', 14, \'bold\'),\n                             bg=\'#e67e22\' if self.gia_registrato else \'#555566\',\n                             fg=\'white\' if self.gia_registrato else \'#999999\',\n                             relief=\'flat\',\n                             cursor=\'hand2\' if self.gia_registrato else \'arrow\',\n                             padx=S(40), pady=S(15),\n                             state=\'normal\' if self.gia_registrato else \'disabled\',\n                             command=self._start_trial)\n        self.btn_trial.pack(pady=S(10))\n\n        self.btn_trial.bind("<Enter>", lambda e: self.gia_registrato and self.btn_trial.config(bg=\'#d35400\'))\n        self.btn_trial.bind("<Leave>", lambda e: self.gia_registrato and self.btn_trial.config(bg=\'#e67e22\'))\n\n        self.lbl_sotto_trial = tk.Label(trial_frame, text=_(\n            "Il programma si chiuderà automaticamente\\ndopo 60 minuti di utilizzo")\n            if self.gia_registrato else _(\n            "Registrati qui sopra per poter entrare:\\nla prova dura 60 minuti e riparte a ogni avvio"),\n                font=F(\'Arial\', 8), bg=\'#1a1a2e\', fg=\'#666666\')\n        self.lbl_sotto_trial.pack()\n\n        \n        # Footer (anno dinamico - si aggiorna automaticamente ogni 1 gennaio)\n        tk.Label(self.root, text=_("© {year} KaraDom - Tutti i diritti riservati").format(year=datetime.now().year),\n                font=F(\'Arial\', 8), bg=\'#1a1a2e\', fg=\'#444444\').pack(side=\'bottom\', pady=S(10))\n    \n    # ──────────────────────────────────────────────────────────\n    # Registrazione: senza, non si entra\n    # ──────────────────────────────────────────────────────────\n    def _registra_dialogo(self):\n        """Controlla i dati e chiede COSA si vuole: prova, Home o Pro."""\n        nome = self.entry_nome.get().strip()\n        cognome = self.entry_cognome.get().strip()\n        email = self.entry_email.get().strip()\n        if not nome or not cognome:\n            messagebox.showwarning(_("Dati mancanti"), _("Inserisci Nome e Cognome."))\n            return\n        if \'@\' not in email or \'.\' not in email:\n            messagebox.showwarning(_("Email non valida"),\n                                   _("Inserisci un indirizzo email valido."))\n            return\n\n        dlg = tk.Toplevel(self.root)\n        dlg.title(_("Cosa vuoi fare?"))\n        dlg.configure(bg=\'#1a1a2e\')\n        dlg.transient(self.root)\n        dlg.grab_set()\n        dlg.resizable(False, False)\n        tk.Label(dlg, text=_("Registrazione di {nome} {cognome}").format(\n            nome=nome, cognome=cognome), font=F(\'Arial\', 12, \'bold\'),\n            bg=\'#1a1a2e\', fg=\'white\').pack(padx=S(24), pady=(S(18), S(4)))\n        tk.Label(dlg, text=_("La licenza si compra dal sito. Qui dici cosa ti serve:\\n"\n                             "se il pagamento risulta, la licenza arriva subito."),\n                 font=F(\'Arial\', 9), bg=\'#1a1a2e\', fg=\'#aaaaaa\',\n                 justify=\'center\').pack(padx=S(24), pady=(0, S(12)))\n        scelta = {\'valore\': None}\n\n        def prendi(v):\n            scelta[\'valore\'] = v\n            dlg.destroy()\n\n        for testo, valore, colore in (\n                (_("▶ Prova gratuita di 60 minuti"), \'prova\', \'#e67e22\'),\n                (_("🏠 Ho comprato la Home"), \'home\', \'#10b981\'),\n                (_("🎤 Ho comprato la Pro"), \'pro\', \'#6366f1\')):\n            tk.Button(dlg, text=testo, font=F(\'Arial\', 11, \'bold\'),\n                      bg=colore, fg=\'white\', relief=\'flat\', cursor=\'hand2\',\n                      pady=S(10), command=lambda v=valore: prendi(v)\n                      ).pack(fill=\'x\', padx=S(24), pady=S(4))\n        tk.Button(dlg, text=_("Annulla"), font=F(\'Arial\', 9), bg=\'#2d2d44\',\n                  fg=\'#aaaaaa\', relief=\'flat\', cursor=\'hand2\',\n                  command=dlg.destroy).pack(pady=(S(10), S(18)))\n        dlg.update_idletasks()\n        dlg.geometry(\'+%d+%d\' % (self.root.winfo_rootx() + S(40),\n                                 self.root.winfo_rooty() + S(80)))\n        self.root.wait_window(dlg)\n        if scelta[\'valore\']:\n            self._registra(scelta[\'valore\'])\n\n    def _registra(self, richiesta):\n        """Manda la registrazione al server e, se il pagamento risulta, riceve\n        la licenza gia\' fatta. Gira in un filo suo: la finestra resta viva."""\n        dati = {\n            \'serial\': self.serial,\n            \'hw_id\': getattr(self, \'hw_id\', \'\'),\n            \'pc_name\': getattr(self, \'pc_name\', \'\'),\n            \'nome\': self.entry_nome.get().strip(),\n            \'cognome\': self.entry_cognome.get().strip(),\n            \'email\': self.entry_email.get().strip(),\n            \'telefono\': getattr(self, \'entry_telefono\', None)\n                        and self.entry_telefono.get().strip() or \'\',\n            \'richiesta\': richiesta,\n            \'versione\': _versione_programma(),\n        }\n        self.btn_registra.config(state=\'disabled\', text=_("Invio…"))\n\n        def torna(msg, titolo=None, sblocca=False, licenza=None):\n            def _fai():\n                self.btn_registra.config(state=\'normal\', text=_("✋ Registrati"))\n                if licenza:\n                    self._attiva_licenza_ricevuta(licenza)\n                    return\n                if sblocca:\n                    self._sblocca_accesso()\n                if msg:\n                    messagebox.showinfo(titolo or _("Registrazione"), msg)\n            try:\n                self.root.after(0, _fai)\n            except Exception:\n                pass\n\n        def lavora():\n            try:\n                corpo = json.dumps(dati).encode(\'utf-8\')\n                req = urllib.request.Request(\n                    REGISTRA_URL, data=corpo, method=\'POST\',\n                    headers={\'Content-Type\': \'application/json\',\n                             \'User-Agent\': \'KaraDom/registrazione\'})\n                with urllib.request.urlopen(req, timeout=20) as r:\n                    risposta = json.loads(r.read().decode(\'utf-8\', \'replace\'))\n            except Exception as e:\n                torna(_("Non riesco a contattare il server.\\n\\n"\n                        "Controlla la connessione e riprova.\\n\\n{err}"\n                        ).format(err=str(e)[:120]), _("Niente rete"))\n                return\n            if not risposta.get(\'ok\'):\n                torna(risposta.get(\'messaggio\') or _("Registrazione non riuscita."),\n                      _("Registrazione"))\n                return\n            _segna_registrazione(self.serial, {\n                \'nome\': dati[\'nome\'], \'cognome\': dati[\'cognome\'],\n                \'email\': dati[\'email\'], \'telefono\': dati[\'telefono\'],\n                \'richiesta\': richiesta, \'stato\': risposta.get(\'stato\'),\n                \'prova_scadenza\': risposta.get(\'prova_scadenza\')})\n            stato = risposta.get(\'stato\')\n            if stato == \'licenza\' and (risposta.get(\'licenza\') or {}).get(\'chiave\'):\n                torna(None, licenza=risposta[\'licenza\'])\n            elif stato == \'in_attesa\':\n                torna(risposta.get(\'messaggio\') or _(\n                    "Non risulta ancora il pagamento: intanto puoi usare la prova."),\n                    _("In attesa del pagamento"), sblocca=True)\n            else:\n                torna(risposta.get(\'messaggio\') or _(\n                    "Registrazione completata: puoi entrare con la prova di 60 minuti."),\n                    _("Registrazione"), sblocca=True)\n\n        threading.Thread(target=lavora, daemon=True).start()\n\n    def _sblocca_accesso(self):\n        """Accende il tasto di accesso: la registrazione c\'e\'."""\n        self.gia_registrato = True\n        try:\n            self.btn_trial.config(state=\'normal\', bg=\'#e67e22\', fg=\'white\',\n                                  cursor=\'hand2\')\n            self.lbl_sotto_trial.config(text=_(\n                "Il programma si chiuderà automaticamente\\ndopo 60 minuti di utilizzo"))\n        except Exception:\n            pass\n\n    def _attiva_licenza_ricevuta(self, licenza):\n        """La licenza e\' arrivata col pagamento gia\' visto: si attiva da sola."""\n        chiave = (licenza or {}).get(\'chiave\') or \'\'\n        edizione = ((licenza or {}).get(\'edizione\') or \'pro\').lower()\n        if edizione not in (\'pro\', \'home\'):\n            edizione = \'pro\'\n        nome = self.entry_nome.get().strip()\n        cognome = self.entry_cognome.get().strip()\n        if not save_license(chiave, nome, cognome, self.serial, edition=edizione):\n            messagebox.showerror(_("Errore"), _("Non riesco a salvare la licenza."))\n            return\n        from .licensing import set_edition\n        set_edition(edizione)\n        avviso = _("✅ Licenza {ed} attivata!\\n\\nBuon lavoro con KaraDom."\n                   ).format(ed=edizione.upper())\n        if (licenza or {}).get(\'declassata\'):\n            avviso = _("⚠️ Risulta l\'acquisto della HOME, non della PRO:\\n"\n                       "e\' stata attivata la licenza HOME.")\n        messagebox.showinfo(_("Licenza attivata"), avviso)\n        self.root.destroy()\n        self.on_continue()\n\n    def _conto_alla_rovescia(self, quanti):\n        """Chi e\' gia\' registrato entra da solo: niente tasti da premere\n        (utente, 13-09). Basta toccare la finestra per fermarlo, cosi\' si puo\'\n        comunque scrivere una licenza."""\n        if not hasattr(self, \'_conto_fermo\'):\n            self._conto_fermo = False\n            for evento in (\'<Button-1>\', \'<Key>\'):\n                try:\n                    self.root.bind_all(evento, lambda e: setattr(self, \'_conto_fermo\', True), add=\'+\')\n                except Exception:\n                    pass\n        if self._conto_fermo:\n            try:\n                self.lbl_trial.config(text=_("Non hai una licenza?"))\n            except Exception:\n                pass\n            return\n        if quanti <= 0:\n            self._start_trial()\n            return\n        try:\n            self.lbl_trial.config(text=_("Entro fra {n}…").format(n=quanti))\n            self.root.after(1000, lambda: self._conto_alla_rovescia(quanti - 1))\n        except Exception:\n            pass\n\n    def _ask_edition_dialog(self):\n        """Mostra un dialog per scegliere l\'edizione da richiedere (Pro o Home).\n        Ritorna \'pro\', \'home\' oppure None se l\'utente annulla."""\n        dlg = tk.Toplevel(self.root)\n        dlg.title(_("Quale licenza?"))\n        dlg.configure(bg=\'#1a1a2e\')\n        dlg.resizable(False, False)\n        dlg.transient(self.root)\n        dlg.grab_set()\n\n        # Centra\n        dlg.update_idletasks()\n        w, h = 460, 360\n        sw = dlg.winfo_screenwidth()\n        sh = dlg.winfo_screenheight()\n        x = (sw - S(w)) // 2\n        y = (sh - S(h)) // 2\n        dlg.geometry(geo(f"{w}x{h}+{x}+{y}"))\n\n        result = {\'value\': None}\n\n        tk.Label(dlg, text=_("Quale licenza vuoi richiedere?"),\n                 font=F(\'Arial\', 14, \'bold\'),\n                 bg=\'#1a1a2e\', fg=\'white\').pack(pady=(S(20), S(10)))\n\n        tk.Label(dlg,\n                 text=_("Se richiedi la Pro ma non hai acquistato la versione Pro,\\n"\n                        "il sistema ti invierà automaticamente la licenza Home."),\n                 font=F(\'Arial\', 9),\n                 bg=\'#1a1a2e\', fg=\'#aaaaaa\', justify=\'center\').pack(pady=(0, S(15)))\n\n        def choose(ed):\n            result[\'value\'] = ed\n            dlg.destroy()\n\n        # Bottone PRO\n        btn_pro = tk.Button(dlg, text=_("🌟 PRO\\n(tutte le funzioni)"),\n                            font=F(\'Arial\', 12, \'bold\'),\n                            bg=\'#28a745\', fg=\'white\', relief=\'flat\',\n                            cursor=\'hand2\', pady=S(14),\n                            command=lambda: choose(\'pro\'))\n        btn_pro.pack(fill=\'x\', padx=S(30), pady=S(6))\n        btn_pro.bind("<Enter>", lambda e: btn_pro.config(bg=\'#218838\'))\n        btn_pro.bind("<Leave>", lambda e: btn_pro.config(bg=\'#28a745\'))\n\n        # Bottone HOME\n        btn_home = tk.Button(dlg, text=_("🏠 HOME\\n(solo libreria + monitor pubblico)"),\n                             font=F(\'Arial\', 12, \'bold\'),\n                             bg=\'#0078D7\', fg=\'white\', relief=\'flat\',\n                             cursor=\'hand2\', pady=S(14),\n                             command=lambda: choose(\'home\'))\n        btn_home.pack(fill=\'x\', padx=S(30), pady=S(6))\n        btn_home.bind("<Enter>", lambda e: btn_home.config(bg=\'#005fa3\'))\n        btn_home.bind("<Leave>", lambda e: btn_home.config(bg=\'#0078D7\'))\n\n        # Annulla\n        btn_cancel = tk.Button(dlg, text=_("Annulla"),\n                               font=F(\'Arial\', 10),\n                               bg=\'#444444\', fg=\'white\', relief=\'flat\',\n                               cursor=\'hand2\', pady=S(8),\n                               command=lambda: choose(None))\n        btn_cancel.pack(fill=\'x\', padx=S(30), pady=(S(10), S(14)))\n\n        dlg.protocol("WM_DELETE_WINDOW", lambda: choose(None))\n        dlg.wait_window()\n        return result[\'value\']\n\n    def _request_license(self):\n        """Invia richiesta licenza al form online.\n\n        Chiede all\'utente quale edizione richiede (Pro o Home). Lato server,\n        se l\'utente richiede Pro ma non ha acquistato la Pro, gli verrà\n        comunque generata una licenza Home (downgrade automatico, gestito\n        dall\'admin nel script di richiesta).\n        """\n        nome = self.entry_nome.get().strip()\n        cognome = self.entry_cognome.get().strip()\n        email = self.entry_email.get().strip()\n\n        if not nome:\n            messagebox.showwarning(_("Dati mancanti"), _("Inserisci il Nome."))\n            return\n        if not cognome:\n            messagebox.showwarning(_("Dati mancanti"), _("Inserisci il Cognome."))\n            return\n        if not email:\n            messagebox.showwarning(_("Dati mancanti"), _("Inserisci l\'Email."))\n            return\n        if \'@\' not in email or \'.\' not in email:\n            messagebox.showwarning(_("Email non valida"), _("Inserisci un indirizzo email valido."))\n            return\n\n        # Chiedi all\'utente quale edizione vuole\n        edition_choice = self._ask_edition_dialog()\n        if edition_choice is None:\n            return  # utente ha annullato\n        edition_requested = edition_choice  # \'pro\' o \'home\'\n\n        # ── Raccolta silenziosa info PC (NON mostrate all\'utente) ──\n        # hw_id = fingerprint hardware (hash CPU+MB)\n        # pc_name = hostname della macchina\n        hw_id, pc_name = _collect_pc_fingerprint(self.hd_id, self.chipset_id)\n\n        # Prepara i dati da inviare\n        edition_label = "Pro" if edition_requested == \'pro\' else "Home"\n        oggetto = f"Richiesta Licenza KaraDom {edition_label}"\n        descrizione = f"""Richiesta di attivazione licenza KaraDom {edition_label}\n\nEdizione richiesta: {edition_label}\nSeriale PC: {self.serial}\n\n---\nRichiesta generata automaticamente da KaraDom."""\n\n        data = {\n            \'nome\': nome,\n            \'cognome\': cognome,\n            \'email\': email,\n            \'oggetto\': oggetto,\n            \'descrizione\': descrizione,\n            \'seriale\': self.serial,   # seriale PC esplicito (oltre che nella descrizione)\n            \'hw_id\': hw_id,           # ⛔ invisibile all\'utente\n            \'pc_name\': pc_name,       # ⛔ invisibile all\'utente\n            \'edition\': edition_requested,  # \'pro\' o \'home\' — il server decide cosa generare\n        }\n\n        # Invia in un thread separato per non bloccare l\'UI\n        def send_request():\n            try:\n                # Codifica i dati\n                encoded_data = urllib.parse.urlencode(data).encode(\'utf-8\')\n\n                # Invia la richiesta POST\n                req = urllib.request.Request(self.CONTACT_URL, data=encoded_data, method=\'POST\')\n                req.add_header(\'Content-Type\', \'application/x-www-form-urlencoded\')\n                req.add_header(\'User-Agent\', \'KaraDom/2.1\')\n                \n                with urllib.request.urlopen(req, timeout=15) as response:\n                    result = response.read().decode(\'utf-8\')\n                    \n                    # Prova a parsare JSON\n                    import json\n                    try:\n                        json_result = json.loads(result)\n                        if json_result.get(\'success\'):\n                            # Costruisci messaggio: se downgrade, avvisa l\'utente\n                            edition_got = (json_result.get(\'edition\') or \'pro\').lower()\n                            downgraded = bool(json_result.get(\'downgraded\'))\n                            if downgraded:\n                                msg = _(\n                                    "⚠️ Richiesta inviata con downgrade automatico.\\n\\n"\n                                    "Hai chiesto la versione PRO, ma il tuo account non risulta\\n"\n                                    "aver acquistato la Pro. Ti è stata generata una licenza HOME.\\n\\n"\n                                    "Riceverai la chiave all\'indirizzo:\\n{email}\\n\\n"\n                                    "Per fare upgrade alla PRO contatta registrazione@karadom.it."\n                                ).format(email=email)\n                            else:\n                                msg = _(\n                                    "✅ Richiesta di licenza {ed} inviata con successo!\\n\\n"\n                                    "Riceverai la licenza all\'indirizzo:\\n{email}\\n\\n"\n                                    "Controlla anche la cartella SPAM."\n                                ).format(ed=edition_got.upper(), email=email)\n                            self.root.after(0, lambda m=msg: messagebox.showinfo(\n                                _("Richiesta Inviata"), m\n                            ))\n                        else:\n                            error_msg = json_result.get(\'message\', _(\'Errore sconosciuto\'))\n                            self.root.after(0, lambda: messagebox.showerror(\n                                _("Errore"), _("❌ {err}").format(err=error_msg)\n                            ))\n                    except json.JSONDecodeError:\n                        # Risposta non JSON - considera successo se status 200\n                        self.root.after(0, lambda: messagebox.showinfo(\n                            _("Richiesta Inviata"),\n                            _("✅ Richiesta inviata!\\n\\n"\n                              "Riceverai la licenza all\'indirizzo:\\n{email}").format(email=email)\n                        ))\n                        \n            except urllib.error.URLError as e:\n                self.root.after(0, lambda: messagebox.showerror(\n                    _("Errore di Connessione"),\n                    _("❌ Impossibile connettersi al server.\\n\\n"\n                      "Verifica la connessione internet e riprova.\\n\\n"\n                      "Errore: {reason}").format(reason=e.reason)\n                ))\n            except Exception as e:\n                self.root.after(0, lambda: messagebox.showerror(\n                    _("Errore"),\n                    _("❌ Errore durante l\'invio:\\n{e}\\n\\n"\n                      "Contatta: {dest}").format(e=e, dest=self.email_dest)\n                ))\n        \n        # Mostra messaggio di attesa\n        messagebox.showinfo(_("Invio in corso"), _("Invio richiesta in corso...\\nAttendi qualche secondo."))\n        \n        # Avvia thread\n        thread = threading.Thread(target=send_request, daemon=True)\n        thread.start()\n    \n    def _activate_license(self):\n        """Attiva la licenza inserita.\n\n        Flusso:\n          1. Verifica i campi obbligatori\n          2. Chiama il server per verificare la licenza e ottenere l\'edizione\n             (pro/home). Una chiave Home non corrisponde mai a una Pro\n             perché l\'edizione è inclusa nell\'hash della chiave.\n          3. Salva localmente con l\'edizione corretta restituita dal server.\n        """\n        nome = self.entry_nome.get().strip()\n        cognome = self.entry_cognome.get().strip()\n        license_key = self.entry_license.get().strip()\n\n        if not nome or not cognome:\n            messagebox.showwarning(_("Dati mancanti"), _("Inserisci Nome e Cognome."))\n            return\n\n        if not license_key:\n            messagebox.showwarning(_("Licenza mancante"), _("Inserisci il codice licenza."))\n            return\n\n        # 1) Verifica sul server PRIMA di salvare, per ottenere l\'edizione reale\n        from .licensing import verify_license_remote, set_edition\n        result = verify_license_remote(nome, cognome, self.serial, license_key)\n\n        if result is None:\n            # Errore di connessione: non possiamo determinare l\'edizione\n            messagebox.showerror(\n                _("Connessione fallita"),\n                _("⚠️ Impossibile contattare il server di licenze.\\n"\n                  "Verifica la connessione a Internet e riprova.")\n            )\n            return\n\n        if result is False or not (isinstance(result, dict) and result.get(\'valid\')):\n            messagebox.showerror(\n                _("Licenza non valida"),\n                _("⚠️ La licenza inserita non è valida o non corrisponde ai dati forniti.\\n\\n"\n                  "Controlla Nome, Cognome e Codice Licenza e riprova.")\n            )\n            return\n\n        # 2) Server ha confermato: estrai edition e salva localmente\n        edition = (result.get(\'edition\') or \'pro\').lower().strip()\n        if edition not in (\'pro\', \'home\'):\n            edition = \'pro\'\n\n        if save_license(license_key, nome, cognome, self.serial, edition=edition):\n            set_edition(edition)\n            # Messaggio di benvenuto specifico per edizione\n            if edition == \'home\':\n                msg = _("✅ Licenza attivata con successo!\\n\\nBenvenuto in KaraDom Home!\\n\\n"\n                        "Puoi fare upgrade alla versione Pro in qualsiasi momento\\n"\n                        "dalle Opzioni → Upgrade Pro.")\n            else:\n                msg = _("✅ Licenza attivata con successo!\\n\\nBenvenuto in KaraDom Pro!")\n            messagebox.showinfo(_("Licenza Attivata"), msg)\n            self.root.destroy()\n            self.on_continue()\n        else:\n            messagebox.showerror(_("Errore"),\n                                _("Impossibile salvare la licenza.\\n"\n                                  "Verifica i permessi della cartella."))\n    \n    def _start_trial(self):\n        """Avvia modalità trial"""\n        # ✅ ENFORCEMENT: il server puo\' aver BLOCCATO questo device (blocco manuale\n        #    admin, trial scaduta o licenza revocata/scaduta). In quel caso la prova\n        #    di 60 minuti NON deve partire. Offline/errore -> grazia (si prosegue).\n        try:\n            from .updater import check_device_status\n            st = check_device_status(self.serial)\n        except Exception:\n            st = None\n        if st and st.get("action") == "block":\n            messagebox.showerror(\n                _("Accesso negato"),\n                st.get("message") or\n                _("Questa copia è stata bloccata. Contatta l\'assistenza.")\n            )\n            return  # resta sulla schermata di attivazione, niente prova\n        self.root.destroy()\n        self.on_trial()\n    \n    def run(self):\n        """Avvia lo splash screen"""\n        if hasattr(self, \'root\'):\n            self.root.mainloop()\n\n\ndef _chiedi_al_server(serial):\n    """Ripassa dal server all\'avvio: dice se la licenza richiesta e\' pronta\n    (il pagamento puo\' essere arrivato dopo), quanti giorni restano di prova e\n    se il PC e\' stato bloccato. Torna la risposta o None se non c\'e\' rete —\n    e senza rete non si blocca niente."""\n    try:\n        with open(_file_registrazione(), encoding=\'utf-8\') as f:\n            d = json.load(f)\n    except Exception:\n        return None\n    richiesta = (d.get(\'richiesta\') or \'prova\').lower()\n    if richiesta not in (\'prova\', \'home\', \'pro\') or not d.get(\'email\'):\n        return None\n    try:\n        from .licensing import _get_pc_fingerprint\n        hw_id, pc_name = _get_pc_fingerprint(*get_hardware_id())\n    except Exception:\n        hw_id, pc_name = \'\', \'\'\n    corpo = json.dumps({\n        \'serial\': serial, \'hw_id\': hw_id, \'pc_name\': pc_name,\n        \'nome\': d.get(\'nome\', \'\'), \'cognome\': d.get(\'cognome\', \'\'),\n        \'email\': d.get(\'email\', \'\'), \'richiesta\': richiesta,\n        \'versione\': _versione_programma(),\n    }).encode(\'utf-8\')\n    try:\n        req = urllib.request.Request(\n            REGISTRA_URL, data=corpo, method=\'POST\',\n            headers={\'Content-Type\': \'application/json\',\n                     \'User-Agent\': \'KaraDom/registrazione\'})\n        with urllib.request.urlopen(req, timeout=10) as r:\n            risposta = json.loads(r.read().decode(\'utf-8\', \'replace\'))\n    except Exception:\n        return None\n    # si tiene l\'ultima scadenza vista: serve alla barra in alto anche offline\n    try:\n        d[\'prova_scadenza\'] = risposta.get(\'prova_scadenza\') or d.get(\'prova_scadenza\')\n        _segna_registrazione(serial, d)\n    except Exception:\n        pass\n    return risposta\n\n\ndef _stato_dal_server(serial):\n    """«Questo computer risulta gia\' registrato?» — una domanda, non una\n    registrazione: il server non scrive niente e non manda mail.\n\n    Serve dopo un AGGIORNAMENTO o una reinstallazione (utente, 13-09: "anche\n    per gli aggiornamenti esce la maschera di registrazione, e\' ovvio che li\'\n    non serve"): se il file locale si e\' perso ma il PC e\' gia\' noto, non si\n    chiede piu\' niente — e se una licenza c\'e\', torna indietro da sola.\n    """\n    try:\n        from .licensing import _get_pc_fingerprint\n        hw_id, pc_name = _get_pc_fingerprint(*get_hardware_id())\n    except Exception:\n        hw_id, pc_name = \'\', \'\'\n    corpo = json.dumps({\'serial\': serial, \'hw_id\': hw_id, \'pc_name\': pc_name,\n                        \'richiesta\': \'stato\', \'solo_stato\': True,\n                        \'versione\': _versione_programma()}).encode(\'utf-8\')\n    try:\n        req = urllib.request.Request(\n            REGISTRA_URL, data=corpo, method=\'POST\',\n            headers={\'Content-Type\': \'application/json\',\n                     \'User-Agent\': \'KaraDom/stato\'})\n        with urllib.request.urlopen(req, timeout=10) as r:\n            risposta = json.loads(r.read().decode(\'utf-8\', \'replace\'))\n    except Exception:\n        return None\n    if not risposta.get(\'registrato\'):\n        return None\n    # ci si segna i dati: al prossimo avvio non serve nemmeno la rete\n    try:\n        d = dict(risposta.get(\'dati\') or {})\n        d[\'stato\'] = risposta.get(\'stato\')\n        d[\'prova_scadenza\'] = risposta.get(\'prova_scadenza\')\n        _segna_registrazione(serial, d)\n    except Exception:\n        pass\n    return risposta\n\n\ndef show_splash(on_continue, on_trial, email_dest="registrazione@karadom.it"):\n    """La finestra di attivazione, MA SOLO A CHI NON SI E\' ANCORA REGISTRATO.\n\n    ⛔ "una volta registrato non devi far vedere questa schermata, anche se in\n       trial" (utente, 13-09): chi si e\' gia\' registrato su questo PC entra\n       diritto nella prova di un\'ora, senza finestre e senza tasti da premere.\n    ⭐ Se aveva chiesto Home o Pro e il pagamento e\' arrivato nel frattempo, la\n       licenza se la prende adesso da sola e il programma parte licenziato.\n    """\n    try:\n        valid, _err, _ed = is_licensed()\n    except Exception:\n        valid = False\n    if not valid:\n        try:\n            serial = generate_serial(*get_hardware_id())\n        except Exception:\n            serial = \'\'\n        # dopo un aggiornamento o una reinstallazione il file locale puo\' non\n        # esserci piu\': prima di mostrare qualcosa si chiede al server se\n        # questo computer e\' gia\' noto (utente, 13-09: "anche per gli\n        # aggiornamenti esce la maschera di registrazione, li\' non serve").\n        risposta = None\n        if serial and not _registrazione_fatta(serial):\n            risposta = _stato_dal_server(serial)\n        if serial and _registrazione_fatta(serial):\n            if risposta is None:\n                # chi e\' solo in prova chiede lo STATO (il server non scrive e\n                # non manda mail); chi aspetta un pagamento rifa\' la richiesta,\n                # perche\' e\' quella che fa nascere la licenza appena il soldo\n                # risulta.\n                try:\n                    _d = json.load(open(_file_registrazione(), encoding=\'utf-8\'))\n                except Exception:\n                    _d = {}\n                if (_d.get(\'richiesta\') or \'prova\').lower() in (\'home\', \'pro\'):\n                    risposta = _chiedi_al_server(serial) or {}\n                else:\n                    risposta = _stato_dal_server(serial) or {}\n            lic = risposta.get(\'licenza\') or {}\n            if risposta.get(\'stato\') == \'licenza\' and lic.get(\'chiave\'):\n                try:\n                    d = json.load(open(_file_registrazione(), encoding=\'utf-8\'))\n                except Exception:\n                    d = {}\n                ed = (lic.get(\'edizione\') or \'pro\').lower()\n                if save_license(lic[\'chiave\'], d.get(\'nome\', \'\'), d.get(\'cognome\', \'\'),\n                                serial, edition=ed if ed in (\'pro\', \'home\') else \'pro\'):\n                    on_continue()\n                    return\n            # prova finita (lo dice il server, o la scadenza che ci siamo\n            # segnati): si torna alla schermata, dove si puo\' mettere la licenza\n            scaduta = (risposta.get(\'stato\') == \'bloccato\')\n            giorni = giorni_prova_rimasti()\n            if not risposta and giorni is not None and giorni < 0:\n                scaduta = True\n            if not scaduta:\n                on_trial()\n                return\n    splash = SplashScreen(on_continue, on_trial, email_dest)\n    splash.run()\n\n\nif __name__ == "__main__":\n    def on_continue():\n        print("✅ Licenza valida - Avvio app")\n    \n    def on_trial():\n        print("⏱️ Modalità trial")\n    \n    show_splash(on_continue, on_trial)'

CODICE_INFO = '# -*- coding: utf-8 -*-\n"""About -> Info: tutto quello che serve di questo computer, in un posto solo.\n\nL\'utente (13-09) l\'ha chiesta cosi\': una terza voce nella barra dei menu,\nAbout, e sotto la voce Info dove si trovano le informazioni utili del PC —\nHW ID, seriale e tutti i dati dati in fase di registrazione — con un bottone\nche rimanda la mail con tutti i dati, e il posto dove mettere la licenza nuova\nin caso di acquisto.\n\nA cosa serve davvero: quando si chiede assistenza, o quando si compra e la\nlicenza va messa a mano, questi sono esattamente i dati che chiediamo. Senza\nquesta finestra l\'utente dovrebbe disinstallare per rivedere la schermata di\nattivazione (che dopo la registrazione non compare piu\').\n"""\n\nimport json\nimport platform\nimport threading\nimport tkinter as tk\nfrom tkinter import messagebox\n\ntry:\n    from .theme import Theme\n    from .i18n import _\n    from .ui_scale import S, F, geo\n    from .licensing import (get_hardware_id, generate_serial, is_licensed,\n                            load_license, save_license, set_edition,\n                            verify_license_remote)\n    from .splash import (REGISTRA_URL, _file_registrazione, _versione_programma,\n                        _collect_pc_fingerprint, giorni_prova_rimasti)\nexcept ImportError:                                    # avvio senza pacchetto\n    from theme import Theme\n    from i18n import _\n    from ui_scale import S, F, geo\n    from licensing import (get_hardware_id, generate_serial, is_licensed,\n                           load_license, save_license, set_edition,\n                           verify_license_remote)\n    from splash import (REGISTRA_URL, _file_registrazione, _versione_programma,\n                        _collect_pc_fingerprint, giorni_prova_rimasti)\n\n# Le etichette un po\' piu\' grandi dei valori, come nella finestra di\n# registrazione (utente, 13-09: "le scritte tutte con lo stesso font e\n# grandezza, un po\' piu\' grandi saranno le etichette dei campi").\n_F_ETICHETTA = 12\n_F_VALORE = 11\n_F_TITOLO = 13\n\n\ndef _dati_registrazione():\n    """Quello che l\'utente ha scritto quando si e\' registrato (se c\'e\')."""\n    try:\n        with open(_file_registrazione(), encoding=\'utf-8\') as f:\n            return json.load(f)\n    except Exception:\n        return {}\n\n\nclass InfoPCWindow:\n    """La finestra di About -> Info."""\n\n    def __init__(self, parent):\n        self.tema = Theme.get()\n        self.riga_widget = {}          # etichetta -> Entry, per copiare tutto\n\n        self.hd_id, self.chipset_id = get_hardware_id()\n        self.serial = generate_serial(self.hd_id, self.chipset_id)\n        self.hw_id, self.pc_name = _collect_pc_fingerprint(self.hd_id,\n                                                           self.chipset_id)\n        self.reg = _dati_registrazione()\n        self.lic = load_license() or {}\n        try:\n            self.licenza_valida, _err, self.edizione = is_licensed()\n        except Exception:\n            self.licenza_valida, self.edizione = False, None\n\n        self.win = tk.Toplevel(parent)\n        self.win.withdraw()\n        self.win.title(_("Info - KaraDom"))\n        self.win.configure(bg=self.tema.win_bg)\n        self.win.resizable(False, True)\n        try:\n            self.win.iconbitmap("img/icona.ico")\n        except Exception:\n            pass\n\n        self._costruisci()\n\n        # ⭐ alta quanto serve, mai oltre lo schermo (come la finestra di\n        #    registrazione: sul portatile 1366x768 il fondo sparirebbe).\n        self.win.update_idletasks()\n        larghezza = S(620)\n        voluta = self.win.winfo_reqheight()\n        libera = self.win.winfo_screenheight() - S(80)\n        altezza = max(S(400), min(voluta, libera))\n        x = (self.win.winfo_screenwidth() - larghezza) // 2\n        y = max(0, (self.win.winfo_screenheight() - altezza) // 2)\n        self.win.geometry(f"{larghezza}x{altezza}+{x}+{y}")\n        self.win.deiconify()\n        self.win.transient(parent)\n        if self.tema.high_contrast:\n            self.tema.apply_to_window(self.win)\n\n    # ────────────────────────── il disegno ──────────────────────────\n    def _titolo_sezione(self, dove, testo):\n        tk.Label(dove, text=testo, font=F(\'Arial\', _F_TITOLO, \'bold\'),\n                 bg=self.tema.win_bg, fg=self.tema.win_fg_accent,\n                 anchor=\'w\').pack(fill=\'x\', pady=(S(12), S(4)))\n\n    def _riga(self, dove, etichetta, valore):\n        """Etichetta a sinistra, valore in un campo che si puo\' selezionare.\n\n        Il valore sta in un Entry di sola lettura e non in una Label: cosi\' si\n        copia col mouse — l\'HW ID e il seriale vanno dettati all\'assistenza.\n        """\n        riga = tk.Frame(dove, bg=self.tema.win_bg)\n        riga.pack(fill=\'x\', pady=S(2))\n        tk.Label(riga, text=etichetta, font=F(\'Arial\', _F_ETICHETTA, \'bold\'),\n                 bg=self.tema.win_bg, fg=self.tema.win_fg,\n                 width=16, anchor=\'w\').pack(side=\'left\')\n        campo = tk.Entry(riga, font=F(\'Consolas\', _F_VALORE),\n                         bg=self.tema.win_bg_input, fg=\'#ffffff\',\n                         readonlybackground=self.tema.win_bg_input,\n                         insertbackground=\'#ffffff\', relief=\'flat\',\n                         highlightthickness=0, bd=0)\n        campo.insert(0, str(valore) if valore not in (None, \'\') else \'—\')\n        campo.config(state=\'readonly\')\n        campo.pack(side=\'left\', fill=\'x\', expand=True, ipady=S(3))\n        self.riga_widget[etichetta] = campo\n        return campo\n\n    def _costruisci(self):\n        t = self.tema\n\n        intestazione = tk.Frame(self.win, bg=t.win_bg_alt)\n        intestazione.pack(fill=\'x\')\n        tk.Label(intestazione, text=_("ℹ️ Info"), font=F(\'Arial\', 18, \'bold\'),\n                 bg=t.win_bg_alt, fg=\'#ffffff\').pack(pady=S(12))\n\n        corpo = tk.Frame(self.win, bg=t.win_bg)\n        corpo.pack(fill=\'both\', expand=True, padx=S(16), pady=(0, S(10)))\n\n        self._titolo_sezione(corpo, _("Questo computer"))\n        self._riga(corpo, _("Seriale"), self.serial)\n        self._riga(corpo, _("HW ID"), self.hw_id)\n        self._riga(corpo, _("Nome PC"), self.pc_name)\n        self._riga(corpo, _("Sistema"),\n                   f"{platform.system()} {platform.release()}")\n        self._riga(corpo, _("Versione"), _versione_programma())\n\n        self._titolo_sezione(corpo, _("Registrazione"))\n        reg = self.reg\n        self._riga(corpo, _("Nome"), reg.get(\'nome\') or self.lic.get(\'nome\'))\n        self._riga(corpo, _("Cognome"),\n                   reg.get(\'cognome\') or self.lic.get(\'cognome\'))\n        self._riga(corpo, _("Email"), reg.get(\'email\') or self.lic.get(\'email\'))\n        self._riga(corpo, _("Telefono"), reg.get(\'telefono\'))\n        self._riga(corpo, _("Richiesta"),\n                   (reg.get(\'richiesta\') or \'\').upper() or None)\n        self._riga(corpo, _("Registrato il"), reg.get(\'quando\'))\n\n        self._titolo_sezione(corpo, _("Licenza"))\n        if self.licenza_valida:\n            stato = _("attiva — {ed}").format(\n                ed=str(self.edizione or \'pro\').upper())\n        else:\n            giorni = giorni_prova_rimasti()\n            if giorni is None:\n                stato = _("nessuna licenza")\n            elif giorni < 0:\n                stato = _("prova scaduta")\n            elif giorni == 0:\n                stato = _("in prova — ultimo giorno")\n            else:\n                stato = _("in prova — {n} giorni").format(n=giorni)\n        self._riga(corpo, _("Stato"), stato)\n        self._riga(corpo, _("Chiave"), self.lic.get(\'license_key\'))\n\n        # ── i due comandi ──\n        comandi = tk.Frame(corpo, bg=t.win_bg)\n        comandi.pack(fill=\'x\', pady=(S(14), S(4)))\n        self.btn_mail = tk.Button(\n            comandi, text=_("📧 Rimanda la mail con i miei dati"),\n            font=F(\'Arial\', _F_ETICHETTA, \'bold\'), bg=\'#0078D7\', fg=\'white\',\n            activebackground=\'#1086e5\', activeforeground=\'white\',\n            relief=\'flat\', cursor=\'hand2\', command=self._rimanda_mail)\n        self.btn_mail.pack(side=\'left\', fill=\'x\', expand=True, ipady=S(6))\n        tk.Button(comandi, text=_("📋 Copia tutto"),\n                  font=F(\'Arial\', _F_ETICHETTA, \'bold\'), bg=\'#666666\',\n                  fg=\'white\', activebackground=\'#777777\',\n                  activeforeground=\'white\', relief=\'flat\', cursor=\'hand2\',\n                  command=self._copia_tutto).pack(side=\'left\', padx=(S(8), 0),\n                                                  ipadx=S(8), ipady=S(6))\n\n        # ── la licenza nuova, in caso di acquisto ──\n        self._titolo_sezione(corpo, _("Hai acquistato? Metti qui la licenza"))\n        self.entry_licenza = tk.Entry(corpo, font=F(\'Consolas\', 12),\n                                      bg=t.win_bg_input, fg=\'#ffffff\',\n                                      insertbackground=\'#ffffff\',\n                                      relief=\'flat\', highlightthickness=0)\n        self.entry_licenza.pack(fill=\'x\', ipady=S(7))\n        self.entry_licenza.bind(\'<Return>\', lambda _e: self._attiva_licenza())\n        self.btn_attiva = tk.Button(\n            corpo, text=_("✅ Attiva la licenza"),\n            font=F(\'Arial\', _F_ETICHETTA, \'bold\'), bg=\'#28a745\', fg=\'white\',\n            activebackground=\'#218838\', activeforeground=\'white\',\n            relief=\'flat\', cursor=\'hand2\', command=self._attiva_licenza)\n        self.btn_attiva.pack(fill=\'x\', pady=(S(6), 0), ipady=S(6))\n\n        tk.Button(corpo, text=_("Chiudi"), font=F(\'Arial\', _F_ETICHETTA),\n                  bg=t.win_bg_input, fg=\'#ffffff\', activeforeground=\'#ffffff\',\n                  relief=\'flat\', cursor=\'hand2\',\n                  command=self.win.destroy).pack(fill=\'x\', pady=(S(12), S(4)),\n                                                 ipady=S(4))\n\n    # ────────────────────────── i comandi ──────────────────────────\n    def _testo_completo(self):\n        righe = [f"{e}: {w.get()}" for e, w in self.riga_widget.items()]\n        return \'\\n\'.join(righe)\n\n    def _copia_tutto(self):\n        try:\n            self.win.clipboard_clear()\n            self.win.clipboard_append(self._testo_completo())\n            messagebox.showinfo(_("Copiato"), _(\n                "I dati sono negli appunti: puoi incollarli in una mail."),\n                parent=self.win)\n        except Exception as e:\n            messagebox.showerror(_("Errore"), str(e)[:200], parent=self.win)\n\n    def _rimanda_mail(self):\n        """Ripassa dal server: rimanda la mail con tutti i dati e, se intanto\n        il pagamento risulta, riporta la licenza (che si attiva da sola)."""\n        nome = (self.reg.get(\'nome\') or self.lic.get(\'nome\') or \'\').strip()\n        cognome = (self.reg.get(\'cognome\') or self.lic.get(\'cognome\') or \'\').strip()\n        email = (self.reg.get(\'email\') or self.lic.get(\'email\') or \'\').strip()\n        if not (nome and cognome and email):\n            messagebox.showwarning(_("Dati mancanti"), _(\n                "Non trovo i dati della registrazione su questo computer.\\n\\n"\n                "Scrivi a assistenza@karadom.it allegando i dati qui sopra "\n                "(tasto “Copia tutto”)."), parent=self.win)\n            return\n\n        dati = {\'serial\': self.serial, \'hw_id\': self.hw_id,\n                \'pc_name\': self.pc_name, \'nome\': nome, \'cognome\': cognome,\n                \'email\': email, \'telefono\': self.reg.get(\'telefono\') or \'\',\n                \'richiesta\': self.reg.get(\'richiesta\') or \'prova\',\n                \'versione\': _versione_programma()}\n        self.btn_mail.config(state=\'disabled\', text=_("Invio…"))\n\n        def torna(msg, titolo, licenza=None):\n            def _fai():\n                try:\n                    self.btn_mail.config(\n                        state=\'normal\',\n                        text=_("📧 Rimanda la mail con i miei dati"))\n                except Exception:\n                    return\n                if licenza and licenza.get(\'chiave\'):\n                    self._salva_e_avvisa(licenza[\'chiave\'], nome, cognome,\n                                         licenza.get(\'edizione\') or \'pro\')\n                    return\n                messagebox.showinfo(titolo, msg, parent=self.win)\n            try:\n                self.win.after(0, _fai)\n            except Exception:\n                pass\n\n        def lavora():\n            import urllib.request\n            try:\n                req = urllib.request.Request(\n                    REGISTRA_URL, data=json.dumps(dati).encode(\'utf-8\'),\n                    method=\'POST\',\n                    headers={\'Content-Type\': \'application/json\',\n                             \'User-Agent\': \'KaraDom/info\'})\n                with urllib.request.urlopen(req, timeout=20) as r:\n                    risposta = json.loads(r.read().decode(\'utf-8\', \'replace\'))\n            except Exception as e:\n                torna(_("Non riesco a contattare il server.\\n\\n"\n                        "Controlla la connessione e riprova.\\n\\n{err}"\n                        ).format(err=str(e)[:120]), _("Niente rete"))\n                return\n            licenza = risposta.get(\'licenza\') if risposta.get(\'ok\') else None\n            if licenza and licenza.get(\'chiave\'):\n                torna(None, _("Licenza"), licenza=licenza)\n                return\n            torna(risposta.get(\'messaggio\') or _(\n                "Mail inviata: i tuoi dati sono arrivati all\'assistenza."),\n                _("Dati inviati"))\n\n        threading.Thread(target=lavora, daemon=True).start()\n\n    def _attiva_licenza(self):\n        chiave = self.entry_licenza.get().strip()\n        if not chiave:\n            messagebox.showwarning(_("Licenza mancante"), _(\n                "Scrivi il codice licenza che hai ricevuto per email."),\n                parent=self.win)\n            return\n        nome = (self.reg.get(\'nome\') or self.lic.get(\'nome\') or \'\').strip()\n        cognome = (self.reg.get(\'cognome\') or self.lic.get(\'cognome\') or \'\').strip()\n        if not (nome and cognome):\n            messagebox.showwarning(_("Dati mancanti"), _(\n                "Non trovo nome e cognome della registrazione: la licenza va "\n                "messa dalla schermata di attivazione."), parent=self.win)\n            return\n\n        self.btn_attiva.config(state=\'disabled\', text=_("Controllo…"))\n\n        def torna(fatto, msg):\n            def _fai():\n                try:\n                    self.btn_attiva.config(state=\'normal\',\n                                           text=_("✅ Attiva la licenza"))\n                except Exception:\n                    return\n                if fatto:\n                    self._salva_e_avvisa(chiave, nome, cognome, msg)\n                else:\n                    messagebox.showerror(_("Licenza non attivata"), msg,\n                                         parent=self.win)\n            try:\n                self.win.after(0, _fai)\n            except Exception:\n                pass\n\n        def lavora():\n            esito = verify_license_remote(nome, cognome, self.serial, chiave)\n            if esito is None:\n                torna(False, _("Non riesco a contattare il server delle "\n                               "licenze. Controlla la connessione."))\n                return\n            if esito is False or not (isinstance(esito, dict)\n                                      and esito.get(\'valid\')):\n                torna(False, _(\n                    "La licenza non risulta valida per questo computer.\\n\\n"\n                    "Controlla di averla copiata per intero; se l\'hai "\n                    "comprata per un altro PC, serve la licenza di questo "\n                    "(seriale {s}).").format(s=self.serial))\n                return\n            torna(True, (esito.get(\'edition\') or \'pro\').lower())\n\n        threading.Thread(target=lavora, daemon=True).start()\n\n    def _salva_e_avvisa(self, chiave, nome, cognome, edizione):\n        edizione = str(edizione or \'pro\').lower()\n        if edizione not in (\'pro\', \'home\'):\n            edizione = \'pro\'\n        if not save_license(chiave, nome, cognome, self.serial,\n                            edition=edizione):\n            messagebox.showerror(_("Errore"), _(\n                "Non riesco a salvare la licenza."), parent=self.win)\n            return\n        try:\n            set_edition(edizione)\n        except Exception:\n            pass\n        messagebox.showinfo(_("Licenza attivata"), _(\n            "✅ Licenza {ed} attivata!\\n\\nRiavvia KaraDom per usarla."\n        ).format(ed=edizione.upper()), parent=self.win)\n        self.win.destroy()\n\n\ndef apri_info_pc(parent):\n    """La voce About -> Info."""\n    try:\n        return InfoPCWindow(parent)\n    except Exception as e:\n        print(f"[info] finestra non aperta: {e}")\n        try:\n            messagebox.showerror(_("Info"), str(e)[:300], parent=parent)\n        except Exception:\n            pass\n        return None\n'

