FATTO = {'barra': False}


def _installa(nome, codice, tag):
    import os
    import types
    import moduli
    breve = nome.split('.')[-1]
    m = sys.modules.get(nome)
    if m is None:
        m = types.ModuleType(nome)
    m.__package__ = 'moduli'
    if not getattr(m, '__file__', None):
        try:
            dove = os.path.dirname(moduli.__file__)
        except Exception:
            dove = os.path.dirname(os.path.abspath(sys.argv[0]))
        m.__file__ = os.path.join(dove, breve + '.py')
    exec(compile(codice, '<%s>' % tag, 'exec'), m.__dict__)
    sys.modules[nome] = m
    setattr(moduli, breve, m)
    return m


def _niente_avviso_registrazione():
    try:
        from moduli import updater as up
    except Exception as e:
        traccia('avviso non tolto: %s' % e)
        return False
    vera = getattr(up, '_handle_registration', None)
    if vera is None or getattr(vera, '_s048', False):
        return False

    def _handle_registration(finestra, reg, _v=vera):
        if (reg or {}).get('action') != 'block':
            try:
                from moduli.licensing import is_licensed
                if is_licensed()[0]:
                    return
            except Exception:
                pass
            try:
                from moduli.licensing import get_hardware_id, generate_serial
                from moduli.splash import _registrazione_fatta
                if _registrazione_fatta(generate_serial(*get_hardware_id())):
                    return
            except Exception:
                pass
        return _v(finestra, reg)

    _handle_registration._s048 = True
    up._handle_registration = _handle_registration
    return True


def _traduzioni():
    try:
        from moduli import i18n
    except Exception as e:
        traccia('traduzioni non messe: %s' % e)
        return

    def versa():
        try:
            d = getattr(i18n, '_translations', None)
            if isinstance(d, dict) and getattr(i18n, '_current_language', 'it') != 'it':
                for k, v in TRADUZIONI.items():
                    d.setdefault(k, v)
        except Exception:
            pass

    vera = getattr(i18n, 'load_language', None)
    if vera is not None and not getattr(vera, '_s048', False):
        def load_language(lang_code, _v=vera):
            r = _v(lang_code)
            versa()
            return r

        load_language._s048 = True
        i18n.load_language = load_language
    versa()


def _menubar(root):
    b = getattr(getattr(root, '_karadom_system', None), '_menubar_frame', None)
    if b is not None:
        return b
    try:
        for f in root.winfo_children():
            for c in f.winfo_children():
                try:
                    if str(c.cget('text')) in ('Strumenti', 'Tools', 'Extra'):
                        return f
                except Exception:
                    continue
    except Exception:
        pass
    return None


def _scritte(barra):
    fuori = []
    try:
        for c in barra.winfo_children():
            try:
                fuori.append(str(c.cget('text')))
            except Exception:
                continue
    except Exception:
        pass
    return fuori


def _about(root, barra):
    import tkinter as tk
    from moduli.i18n import _
    from moduli.theme import Theme
    from moduli.ui_scale import S, F
    if any(t in ('About',) for t in _scritte(barra)):
        return False
    t = Theme.get()

    menu = tk.Menu(root, tearoff=0)
    try:
        t.style_menu(menu)
    except Exception:
        pass

    def apri():
        try:
            from moduli.info_pc import apri_info_pc
            apri_info_pc(root)
        except Exception as e:
            traccia('finestra Info non aperta: %s' % e)

    menu.add_command(label=_('Info'), command=apri)

    def mostra():
        try:
            x = tasto.winfo_rootx()
            y = tasto.winfo_rooty() + tasto.winfo_height()
            menu.tk_popup(x, y)
        except Exception:
            pass

    try:
        import customtkinter as ctk
        tasto = ctk.CTkButton(barra, text=_('About'), width=S(60), height=S(28),
                              fg_color='transparent', hover_color=t.menu_hover,
                              text_color=t.menu_fg, font=F('Arial', 14),
                              anchor='w', command=mostra)
    except Exception:
        tasto = tk.Button(barra, text=_('About'), bg=t.menu_bg, fg=t.menu_fg,
                          activebackground=t.menu_hover, relief='flat',
                          font=F('Arial', 14), command=mostra)
    tasto.pack(side='left', padx=0, pady=S(2))
    return True


def _conto_prova(barra):
    import tkinter as tk
    from moduli.i18n import _
    from moduli.theme import Theme
    from moduli.ui_scale import S, F
    if any('Prova' in t or 'Trial' in t for t in _scritte(barra)):
        return False
    try:
        from moduli.licensing import is_licensed
        from moduli.splash import giorni_prova_rimasti
        valida, _e, _ed = is_licensed()
        if valida:
            return False
        giorni = giorni_prova_rimasti()
    except Exception as e:
        traccia('conto alla rovescia non letto: %s' % e)
        return False
    if giorni is None:
        return False
    t = Theme.get()
    testo = (_('Prova: ultimo giorno') if giorni == 0 else
             _('Prova scaduta') if giorni < 0 else
             _('Prova: {n} giorni').format(n=giorni))
    tk.Label(barra, text=testo, bg=t.menu_bg,
             fg='#ffffff' if giorni > 3 else '#ff6b6b',
             font=F('Arial', 10, 'bold')).pack(side='right', padx=S(12))
    return True


def _cerca(root, quante):
    if FATTO['barra']:
        return
    barra = _menubar(root)
    if barra is None:
        if quante < 10:
            try:
                root.after(1000, _cerca, root, quante + 1)
            except Exception:
                pass
        else:
            traccia('barra dei menu non trovata')
        return
    FATTO['barra'] = True
    fatti = []
    try:
        if _about(root, barra):
            fatti.append('About > Info')
    except Exception as e:
        traccia('About non aggiunto: %s' % e)
    try:
        if _conto_prova(barra):
            fatti.append('giorni di prova')
    except Exception as e:
        traccia('conto alla rovescia non aggiunto: %s' % e)
    if fatti:
        traccia('in alto: ' + ', '.join(fatti))


def _aggancia_avvio():
    import tkinter
    vera = tkinter.Tk.mainloop
    if getattr(vera, '_s048', False):
        return

    def mainloop(self, n=0, _v=vera):
        if not FATTO['barra']:
            try:
                self.after(1500, _cerca, self, 0)
            except Exception:
                pass
        return _v(self, n)

    mainloop._s048 = True
    tkinter.Tk.mainloop = mainloop


def apply():
    try:
        vecchio = sys.modules.get('moduli.splash')
        if vecchio is not None and hasattr(vecchio, 'REGISTRA_URL') \
                and not getattr(vecchio, '_s048', False):
            traccia('il programma lo fa gia da se')
            return True
        m = _installa('moduli.splash', CODICE_SPLASH, 'patch048_splash')
        m._s048 = True
        traccia('registrazione, HW ID e prova di 15 giorni')
        _installa('moduli.info_pc', CODICE_INFO, 'patch048_info')._s048 = True
        traccia('finestra Info pronta')
        if _niente_avviso_registrazione():
            traccia('niente avviso "registra la tua copia" a chi e- registrato')
        _traduzioni()
        _aggancia_avvio()
        return True
    except Exception as e:
        traccia('non agganciata: %s: %s' % (type(e).__name__, e))
        return False


def revert():
    return False


try:
    apply()
except Exception:
    pass
